# 结构化留痕（同 dsh-toast.ps1 格式）：restart.start / restart.setup，带 run 关联 ID 与耗时
`$logPath = Join-Path `$installRaw 'dsh-tray.log'
`$utf8NoBom = New-Object System.Text.UTF8Encoding(`$false)
`$logLost = 0
function Write-DshRecord2([string]`$Rec) {
    # 主日志 → %TEMP% 降级 → 计数（coding-log-monitor H9：不留空 catch，捕获必留上下文）
    `$nl2 = [Environment]::NewLine
    try { [IO.File]::AppendAllText(`$logPath, (`$Rec + `$nl2), `$utf8NoBom); return `$true }
    catch { `$err1 = `$_.Exception.GetType().Name + ': ' + `$_.Exception.Message }
