    try {
        `$p = Start-Process -FilePath 'powershell.exe' -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-File',`$setupArg,'-InstallDir',`$installArg,'-NoShortcut' -WindowStyle Hidden -PassThru -ErrorAction Stop -RedirectStandardOutput ([IO.Path]::ChangeExtension('$statusEsc','.setup.out.log')) -RedirectStandardError ([IO.Path]::ChangeExtension('$statusEsc','.setup.err.log'))
        # 2026-11-07：PowerShell 5.1 下，Start-Process 带 redirect 且用 Wait-Process 时 ExitCode 恒为空
        # （PS7 正常，实测 5.1.19041 复现）。先访问一次 .Handle 强制填充退出码，再等待。
        try { `$null = `$p.Handle } catch {}
