            if (-not `$setupCode) { `$setupState = 'failed'; `$setupCode = 'unknown' }
            elseif (`$setupCode -ne '0') { `$setupState = 'failed' }
        }
    } catch { `$setupState = 'failed'; `$setupCode = 'launch-error' }
}
# 注意：元素一律加括号。PowerShell 里 @('a=' + x, 'b=' + y) 这种"字符串拼接 + 逗号"会被并成
